{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.sku_group_sample_to_live as ( with live_date_pre as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, min(PUBLISHEDAT::date) as live_date, lower(status) as status from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value group by 1,3 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), live_date as ( select sku_group, status, live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), inwards as ( select sku_group, date, sum(inwared_quantity) as quant from snitch_db.maplemonk.Inwards where upper(sku_group) not like \'%MP-%\' group by 1,2 ), catalog as ( select replace(upper(trim(sku_group)),\'MP-\',\'\') as sku_group, \'not_in_shopify\' as status, min(date) as latest_inward_date, sum(quant) as units_on_hand from inwards where quant > 0 group by 1 ), base_cte AS ( SELECT DISTINCT REGEXP_REPLACE(UPPER(barcode), \'-[^-]+$\', \'\') AS sku_group, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(sample_received_date_shoot), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS sample_received_ts, MAX(TO_TIMESTAMP_NTZ(FLOOR(TRY_TO_NUMBER(TRIM(edit_complete_time)) / 1000))) AS edit_complete_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(catalogus_sent_time_stamp), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS catalogix_sent_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(catalogus_received_time_stamp), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS catalogix_received_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(production_creation_date), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS production_creation_ts, MAX(TRY_TO_TIMESTAMP(NULLIF(TRIM(scheduled_shoot_date), \'\'), \'DD-MM-YYYY HH24:MI:SS\')) AS scheduled_shoot_ts, MAX(factory) AS factory, MAX(editor_name) AS editor_name, MAX(photoshoot_status) AS photoshoot_status, MAX(image_selection) AS image_selection, MAX(shoot_tags) AS shoot_tags, MAX(production_sku_created_by) AS production_sku_created_by FROM snitch_db.maplemonk.pslj_pslj_table WHERE TRIM(barcode) IS NOT NULL GROUP BY REGEXP_REPLACE(UPPER(barcode), \'-[^-]+$\', \'\') ), sample_received_date AS ( SELECT sku_group, sample_recieved_date FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY sample_recieved_date DESC NULLS LAST ) AS rn FROM ( SELECT DISTINCT UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(sku_group), CHARINDEX(\'-\', REVERSE(sku_group)) + 1, LEN(sku_group))))) AS sku_group, TO_CHAR(TRY_TO_DATE(sample_recieved_date, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS sample_recieved_date FROM snitch_db.maplemonk.google_Sheet_sample_recieved UNION ALL SELECT sku_group, sample_received_ts::DATE AS sample_recieved_date FROM base_cte ) AS combined ) AS ranked_sample_received WHERE rn = 1 ), PSLJ AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY edit_received_date DESC NULLS LAST ) AS rn FROM ( SELECT replace((upper(trim(sku))),\'MP-\',\'\') as sku_group, a.\"Factory_\'\", a.selection_ as editor_owner, a.shoot_date as photoshoot_status, a.tagging as IMAGE_SELECTION, TO_CHAR(COALESCE(TRY_TO_TIMESTAMP(a.owner, \'YYYY-MM-DD\'), TRY_TO_TIMESTAMP(a.owner, \'DD/MM/YYYY\')), \'YYYY-MM-DD\') AS edit_received_date, TO_CHAR(COALESCE(TRY_TO_TIMESTAMP(a.editing_status, \'YYYY-MM-DD\'), TRY_TO_TIMESTAMP(a.editing_status, \'DD/MM/YYYY\')), \'YYYY-MM-DD\') AS edit_completed_date, TO_CHAR(COALESCE(TRY_TO_TIMESTAMP(a.final_shared_date, \'YYYY-MM-DD\'), TRY_TO_TIMESTAMP(a.final_shared_date, \'DD/MM/YYYY\')), \'YYYY-MM-DD\') AS catalogix_sent_timestamp, TO_CHAR(COALESCE(TRY_TO_TIMESTAMP(a.final_recieved_date, \'YYYY-MM-DD\'), TRY_TO_TIMESTAMP(a.final_recieved_date, \'DD/MM/YYYY\')), \'YYYY-MM-DD\') AS catalogix_received_timestamp, TO_CHAR(COALESCE(TRY_TO_TIMESTAMP(a.live_on_shopify_date, \'YYYY-MM-DD\'), TRY_TO_TIMESTAMP(a.live_on_shopify_date, \'DD/MM/YYYY\')), \'YYYY-MM-DD\') AS live_on_shopify_date, NULL as PRODUCTION_CREATION_DATE, tags as wtw_tags, production_poc from snitch_db.maplemonk.gs_pslj a where upper(sku) not like \'%MP-%\' NULL as PRODUCTION_CREATION_DATE, tags as wtw_tags, production_poc from snitch_db.maplemonk.gs_pslj a where upper(sku) not like \'%MP-%\' UNION ALL SELECT REPLACE(sku_group, \'MP-\', \'\') AS sku_group, factory, editor_name AS editor_owner, photoshoot_status, image_selection, TO_CHAR(sample_received_ts, \'YYYY-MM-DD\') AS edit_received_date, TO_CHAR(edit_complete_ts, \'YYYY-MM-DD\') AS edit_completed_date, TO_CHAR(catalogix_sent_ts, \'YYYY-MM-DD\') AS catalogix_sent_timestamp, TO_CHAR(catalogix_received_ts, \'YYYY-MM-DD\') AS catalogix_received_timestamp, NULL AS live_on_shopify_date, TO_CHAR(production_creation_ts, \'YYYY-MM-DD\') AS production_creation_date, shoot_tags AS wtw_tags, PRODUCTION_SKU_CREATED_BY AS production_poc FROM base_cte WHERE UPPER(sku_group) NOT LIKE \'%MP-%\' ) combined ) ranked_pslj WHERE rn = 1 ), shoot_date AS ( SELECT * FROM ( SELECT DISTINCT UPPER(REGEXP_REPLACE(sku, \'-[^-]+$\', \'\')) AS sku_group, TO_DATE(TRY_TO_DATE(date, \'DD/MM/YYYY\')) AS shoot_date FROM snitch_db.maplemonk.gs_shoot_date UNION SELECT DISTINCT sku_group, scheduled_shoot_ts::DATE AS shoot_date FROM base_cte ) all_shoots QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY shoot_date DESC NULLS LAST ) = 1 ), RTS AS ( SELECT replace(upper(trim(sku)),\'MP-\',\'\') as sku_group, CLASS, \'ready_to_dispatch\' as status, REPEAT, VENDOR, WAEHOUSE, DESCIPTON, TO_CHAR(TRY_TO_DATE(DELIVEY_DATE_, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') as DELIVERY_DATE, online_qty, QC_STATUS, QC_REPORT FROM snitch_db.maplemonk.catalog_main where repeat = \'NO\' and upper(trim(sku)) not in (select sku_group from catalog) and (upper(sku) not like \'%MP-%\' or upper(sku) not like \'MP%\') ), inventory as ( select replace(upper(trim(sku_group)),\'MP-\',\'\') as sku_group, sellable_inventory as inventory from snitch_db.maplemonk.availability_master_v2 where upper(sku_group) not like \'%MP-%\' ), main_data as ( select coalesce(a.sku_group,c.SKU_GROUP,r.sku_group) as sku_group, sr.sample_recieved_date::date as sample_received_date, l.live_date::date as live_date, a.Photoshoot_Status, sd.shoot_date::date as shoot_date, a.edit_received_date, a.editor_owner, a.edit_completed_date, a.catalogix_sent_timestamp, a.catalogix_received_timestamp, a.production_poc, r.delivery_date, a.production_creation_date, cast(greatest(coalesce(r.online_qty,0),coalesce(c.units_on_hand,0),coalesce(i.inventory,0)) as number) as units_on_hand, c.latest_inward_date as inward_date, case when a.sku_group is null and c.sku_group is not null then \'not_in_PSLJ\' else \'present_in_PSLJ\' end as pslj_status, coalesce(l.status,c.status,r.status) as status, DATEDIFF(day, sr.sample_recieved_date, l.live_date) AS sr_live_tat, DATEDIFF(day, sr.sample_recieved_date, sd.shoot_date) AS shoot_tat, datediff(day,sd.shoot_date,a.edit_received_date) as shootdone_editreceived_tat, datediff(day,a.edit_received_date,a.edit_completed_date) as edit_tat, datediff(day,a.edit_completed_date,a.catalogix_sent_timestamp) as editdone_catalogixsent_tat, datediff(day,a.catalogix_sent_timestamp,a.catalogix_received_timestamp) as catalogix_tat, datediff(day,a.catalogix_received_timestamp,l.live_date) as live_tat, a.wtw_tags FROM PSLJ a FULL OUTER JOIN catalog c ON a.sku_group = c.sku_group FULL OUTER JOIN RTS r ON COALESCE(a.sku_group, c.SKU_GROUP) = r.sku_group FULL OUTER JOIN live_date l ON COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = l.sku_group left join inventory i on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = i.sku_group left join sample_received_date sr on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sr.sku_group left join shoot_date sd on COALESCE(a.sku_group, c.SKU_GROUP, r.sku_group) = sd.sku_group ), main_data2 as ( select *, CASE when lower(status) = \'active\' or live_date is not null then \'NO_ISSUES\' when lower(status) = \'ready_to_dispatch\' and live_date is not null then \'NO_ISSUES\' when lower(status) = \'draft\' and inward_date is not null then \'QC\' when lower(status) = \'draft\' and inward_date is null then \'CATALOG_INWARD_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is null and sample_received_date is not null then \'RTS_SHOOT_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and (EDIT_RECEIVED_DATE is null or edit_completed_date is null) then \'RTS_EDIT_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null then \'RTS_CATALOG_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is null then \'RTS_INWARD_NOT_DONE\' when lower(status) = \'ready_to_dispatch\' and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and CATALOGIX_SENT_TIMESTAMP is not null and catalogix_received_timestamp is not null and inward_date is not null then \'RTS_QC\' when lower(status) not in (\'active\',\'draft\') and production_creation_Date is null and sample_received_date is null then \'SAMPLE_NOT_RECEIVED_IN_HQ\' when lower(status) not in (\'active\',\'draft\') and production_creation_Date is not null and sample_received_date is null then \'SAMPLE_NOT_HANDOVER\' when lower(status) not in (\'active\',\'draft\') and sample_received_date is null and shoot_date is null then \'SAMPLE_NOT_RECEIVED\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and sample_received_date is not null and shoot_date is null then \'SHOOT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and (edit_completed_date is null or EDIT_RECEIVED_DATE is null) then \'EDIT_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null then \'CATALOG_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is null then \'INWARD_NOT_DONE\' when lower(status) not in (\'ready_to_dispatch\',\'active\',\'draft\') and shoot_date is not null and edit_completed_date is not null and EDIT_RECEIVED_DATE is not null and catalogix_received_timestamp is not null and CATALOGIX_SENT_TIMESTAMP is not null and inward_date is not null then \'QC\' else \'others\' end as final_status from main_data ), metafields_pre as ( select SKU_GROUP, SAMPLE_RECEIVED_DATE, LIVE_DATE, PHOTOSHOOT_STATUS, SHOOT_DATE, EDITOR_OWNER, DELIVERY_DATE, UNITS_ON_HAND, INWARD_DATE, PSLJ_STATUS, STATUS, SR_LIVE_TAT, SHOOT_TAT, SHOOTDONE_EDITRECEIVED_TAT, EDIT_TAT, EDITDONE_CATALOGIXSENT_TAT, CATALOGIX_TAT, LIVE_TAT, FINAL_STATUS,wtw_tags, production_poc, production_creation_date, TRY_TO_DATE(edit_received_date, \'YYYY-MM-DD\') AS edit_received_date, TRY_TO_DATE(EDIT_COMPLETED_DATE, \'YYYY-MM-DD\') AS edit_completed_date, TRY_TO_DATE(CATALOGIX_SENT_TIMESTAMP,\'YYYY-MM-DD\') AS catalogix_sent_timestamp, TRY_TO_DATE(CATALOGIX_RECEIVED_TIMESTAMP,\'YYYY-MM-DD\') AS catalogix_received_timestamp from main_data2 ), sample_shoot_tracker AS ( SELECT sku_group, sample_shoot, SAMPLE_RECIEVED_DATE_to_shot, sample_returned_date_to_shoot, SAMPLE_OUT_FOR_SHOOT_DATE FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY sample_shoot DESC NULLS LAST ) AS rn FROM ( SELECT UPPER(TRIM(sku_group)) AS sku_group, TRY_TO_DATE(sample_shoot, \'DD/MM/YYYY\') AS sample_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_RECIEVED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS SAMPLE_RECIEVED_DATE_to_shot, TO_CHAR(TRY_TO_DATE(SAMPLE_RETURNED_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS sample_returned_date_to_shoot, TO_CHAR(TRY_TO_DATE(SAMPLE_OUT_FOR_SHOOT_DATE, \'DD/MM/YYYY\'), \'YYYY-MM-DD\') AS SAMPLE_OUT_FOR_SHOOT_DATE FROM snitch_db.maplemonk.shoot_sample_tracker_Sheet1 UNION ALL SELECT sku_group, sample_received_ts::DATE AS sample_shoot, NULL AS SAMPLE_RECIEVED_DATE_to_shot, NULL AS sample_returned_date_to_shoot, TO_CHAR(scheduled_shoot_ts, \'YYYY-MM-DD\') AS SAMPLE_OUT_FOR_SHOOT_DATE FROM base_cte ) combined ) ranked_tracker WHERE rn = 1 ) select a.*, occassion_new, occassion, print_design, collar, product_tags, material_new, material, rise, pocket, sleeve_type, fit, color, closure, length, vendor, designs, style, sample_shoot, SAMPLE_RECIEVED_DATE_to_shot, sample_returned_date_to_shoot, SAMPLE_OUT_FOR_SHOOT_DATE from metafields_pre a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group left join sample_shoot_tracker c on a.sku_group = c.sku_group where upper(a.sku_group) not like \'MP%\' and a.sku_group not in (\'4MSFR0918\',\'4MSK8662-01\',\'4MSK8662-02\',\'4MSK8662-03\',\'4MSK8662-04\',\'4MSN1310-08\',\'4MSN1310-05\',\'4MSN1310-02\',\'4MST0218-03-T-SHIRT\',\'4MST0226-01-T-SHIRT\',\'4MTR0123-02\',\'4MTR0123-04\',\'4MSN1345-11-SHIRT\',\'4MSN1310-01-SHIRT\',\'4MSN1345-10-SHIRT\',\'4MSN1310-04-SHIRT\',\'4MSN1345-06-SHIRT\',\'4MSN1345-05-SHIRT\',\'4MSN1310-09-SHIRT\',\'4MSN1310-03-SHIRT\',\'4MSO3690-02\',\'4MTP0025-04\',\'4MSN1075-07-SHIRT\',\'4MST0224-01-T-SHIRT\',\'4MSN1310-10-SHIRT\',\'4MSS2142-16\',\'4MSS2142-11\',\'4MSS2648-5\',\'4MSS1813-25\',\'4MSS1813-24\',\'4MSS1813-16\',\'4MSS1813-17\',\'4MSS1813-11\',\'4MSS1813-26\',\'4MSS1813-12\',\'4MST2066-02\',\'4MSS3166-02\',\'4MSR5053-03\',\'4MSS1813-21\',\'4MSFR0929_T\',\'4MSFR0928_T\',\'4MSFR0927_T\',\'4MSFR0925_T\',\'4MSFR0926_T\',\'4MSD3516-04\',\'4MSD3516-02\',\'4MSS1203-18\',\'SH0038-03\',\'4MSFR0919\',\'4MSFR0920\',\'4MSFR0921\',\'4MSFR0922\',\'4MSFR0923\',\'4MSFR0924\',\'4MSS2304\',\'4MSS2651-04\',\'4MSS2651-02\',\'4MSS2651-07\',\'4MSS2651-05\',\'4MSS2651-01\',\'4MSS2651-06\',\'4MSS2651-03\',\'4MSO4505-02\',\'4MSO4505-01\',\'4MSR5062-02\',\'4MST0217-10\',\'4MSS2623- 01\',\'4MSS2623- 02\',\'4MSS2623- 04\',\'4MSS2935-03\',\'4MSS2935-04\',\'4MSS2935-01\',\'4MSS2935-02\',\'4MSD3703-06\',\'4MSS3302-2\',\'4MSS3302-1\',\'4MS04584-03\',\'4MBGSS1026-06\',\'4MSS3120\',\'4MST2343\',\'4MST2345\',\'4MSS3305\',\'4MSS3121\',\'4MSS3161\',\'4MST2344\',\'4MSW9899-01\',\'4MSW9898-01\',\'MPSS1001-02\',\'MPSS1001-03\',\'MPSS1001-01\',\'MPSS1001-06\',\'MPSS1001-05\') );",
